cypress_script:
describe('Checkout Information Form', () => {
  it('should submit form with valid inputs and navigate to next page', () => {
    cy.visit('https://www.saucedemo.com/checkout-step-one.html');
    cy.get('[data-test="firstName"]').type('John');
    cy.get('[data-test="lastName"]').type('Doe');
    cy.get('[data-test="postalCode"]').type('12345');
    cy.get('[data-test="continue"]').click();
    cy.url().should('not.eq', 'https://www.saucedemo.com/checkout-step-one.html');
  });
  it('should not navigate if fields are empty', () => {
    cy.visit('https://www.saucedemo.com/checkout-step-one.html');
    cy.get('[data-test="continue"]').click();
    cy.url().should('eq', 'https://www.saucedemo.com/checkout-step-one.html');
    cy.get('[data-test="firstName"]').should('be.visible');
    cy.get('[data-test="lastName"]').should('be.visible');
    cy.get('[data-test="postalCode"]').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';
test.describe('Checkout Information Form', () => {
  test('should submit form with valid inputs and navigate to next page', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/checkout-step-one.html');
    await page.fill('[data-test="firstName"]', 'John');
    await page.fill('[data-test="lastName"]', 'Doe');
    await page.fill('[data-test="postalCode"]', '12345');
    await page.click('[data-test="continue"]');
    await expect(page).toHaveURL(/checkout-step-two/);
  });
  test('should not navigate if fields are empty', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/checkout-step-one.html');
    await page.click('[data-test="continue"]');
    await expect(page).toHaveURL('https://www.saucedemo.com/checkout-step-one.html');
    await expect(page.locator('[data-test="firstName"]')).toBeVisible();
    await expect(page.locator('[data-test="lastName"]')).toBeVisible();
    await expect(page.locator('[data-test="postalCode"]')).toBeVisible();
  });
});
